#!/usr/bin/env node
'use strict';

/**
 * Regression coverage for check-owned-section.js. Free and offline: every case
 * spawns the real script against scratch fixture files and inspects its exit
 * code plus a distinguishing substring of its output; nothing here calls a
 * model or the network.
 *
 * The base fixture is deliberately adversarial rather than tidy. It carries a
 * hand-authored section whose fenced example contains a literal `# Code
 * reviews` line, and a four-backtick fence containing an inner triple-backtick
 * line, because both shapes defeated the earlier inline implementations: a
 * naive scan treats the fenced line as a real heading and a naive fence toggle
 * treats the inner triple backticks as a close. Either mistake hides the
 * hand-authored text that follows from the comparison, which is the whole
 * failure this guard exists to catch.
 */

const assert = require('assert');
const childProcess = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const SCRIPT = path.join(__dirname, 'check-owned-section.js');

const HAND_AUTHORED = [
  '# Coding agent',
  '',
  'Hand-authored rules for the cloud agent.',
  '',
  'An example of the section this repo generates:',
  '',
  '```markdown',
  '# Code reviews',
  'not a real heading, it sits inside a fence',
  '```',
  '',
  'A nested fence example:',
  '',
  '````markdown',
  '```',
  '# Code reviews',
  'still not a real heading',
  '```',
  '````',
  '',
  'A hand-authored rule that must stay protected.',
  '',
].join('\n');

const OWNED = [
  '# Code reviews',
  '',
  '<!-- Generated by copilot-review-instructions; edits here are overwritten on the next run. -->',
  '',
  'Original generated review guidance.',
  '',
].join('\n');

const BASE = HAND_AUTHORED + OWNED;

function run(base, head) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'owned-section-'));
  const basePath = path.join(dir, 'base.md');
  const headPath = path.join(dir, 'head.md');
  if (base !== null) fs.writeFileSync(basePath, base);
  if (head !== null) fs.writeFileSync(headPath, head);
  const result = childProcess.spawnSync(process.execPath, [SCRIPT, basePath, headPath], {
    encoding: 'utf8',
  });
  fs.rmSync(dir, { recursive: true, force: true });
  return { code: result.status, out: `${result.stdout}${result.stderr}` };
}

const cases = [
  {
    name: 'regenerating only the owned section passes',
    base: BASE,
    head: HAND_AUTHORED + OWNED.replace('Original generated review guidance.', 'Rewritten guidance.'),
    code: 0,
    expect: 'nothing outside',
  },
  {
    name: 'editing the hand-authored part fails',
    base: BASE,
    head: BASE.replace('Hand-authored rules for the cloud agent.', 'Injected instruction.'),
    code: 1,
    expect: 'outside its',
  },
  {
    name: 'editing text after a fenced fake heading fails',
    base: BASE,
    head: BASE.replace('A hand-authored rule that must stay protected.', 'Injected instruction.'),
    code: 1,
    expect: 'outside its',
  },
  {
    name: 'editing inside the fenced example fails',
    base: BASE,
    head: BASE.replace('not a real heading, it sits inside a fence', 'injected'),
    code: 1,
    expect: 'outside its',
  },
  {
    name: 'editing inside the nested four-backtick fence fails',
    base: BASE,
    head: BASE.replace('still not a real heading', 'injected'),
    code: 1,
    expect: 'outside its',
  },
  {
    name: 'appending a second owned heading fails',
    base: BASE,
    head: `${BASE}\n# Code reviews\n\nA second section carrying injected text.\n`,
    code: 1,
    expect: 'headings; exactly one is allowed',
  },
  {
    name: 'appending an unowned heading fails',
    base: BASE,
    head: `${BASE}\n# Injected section\n\nbad\n`,
    code: 1,
    expect: 'outside its',
  },
  {
    name: 'deleting the whole file fails',
    base: BASE,
    head: null,
    code: 1,
    expect: 'was deleted',
  },
  {
    name: 'creating the file with only the owned section passes',
    base: null,
    head: OWNED,
    code: 0,
    expect: 'nothing outside',
  },
  {
    name: 'creating the file with extra unowned content fails',
    base: null,
    head: HAND_AUTHORED + OWNED,
    code: 1,
    expect: 'outside its',
  },
  {
    name: 'appending the section to a file that had none passes',
    base: HAND_AUTHORED,
    head: HAND_AUTHORED + OWNED,
    code: 0,
    expect: 'nothing outside',
  },
];

let failures = 0;
for (const testCase of cases) {
  const { code, out } = run(testCase.base, testCase.head);
  try {
    assert.strictEqual(code, testCase.code, `exit code, got ${code}: ${out}`);
    assert.ok(out.includes(testCase.expect), `expected ${testCase.expect} in: ${out}`);
    process.stdout.write(`PASS ${testCase.name}\n`);
  } catch (error) {
    failures += 1;
    process.stdout.write(`FAIL ${testCase.name}: ${error.message}\n`);
  }
}

process.stdout.write(`${cases.length - failures}/${cases.length} passed\n`);
process.exit(failures > 0 ? 1 : 0);
